	output = "eDP-1",
	mode = "1920x1080@144",
	position = "auto",
	scale = 1.2,
})

hl.monitor({
	output = "HDMI-A-1",
	mode = "1920x1080@120",
	position = "auto",
	scale = 1,
})

hl.workspace_rule({
	workspace = "name:shell",
	monitor = "eDP-1",
	default = true,
})

hl.workspace_rule({
	workspace = "name:web",
	monitor = "HDMI-A-1",
	on_created_empty = "brave",
})

hl.workspace_rule({
	workspace = "special:notes",
	on_created_empty = "obsidian",
})

hl.workspace_rule({
	workspace = "special:music",
	on_created_empty = "pear-desktop",
})

hl.workspace_rule({
	workspace = "special:exposed",
	gaps_out = 60,
	gaps_in = 30,
	border_size = 5,
})

